Item.method_code:
/*
    リレーション追加時に、配下アイテムに一括承認アイテムを記録する
    対象アイテム：
        親：一括承認,開達実施要領一括承認
        子：マルQページ,必要資料,開達書式
*/

Innovator inn = this.getInnovator();

var sourceID = this.getProperty("source_id","");
var relatedID = this.getProperty("related_id","");

string relatedType = "";
if(this.getType() == "h4_AppWFGr4DATFormat DATFormat")
{
    relatedType = "h4_DATFormat";
}
else if(this.getType() == "h4_ApprovalWFGroup_ApTarget")
{
    var targetItem = inn.newItem("h4_ApprovalTarget","get");
    targetItem.setID(relatedID);
    targetItem.setAttribute("select","id");
    targetItem = targetItem.apply();
    if(targetItem.isError())
    {
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
    relatedType = targetItem.getType();
}

Item updateItem = inn.newItem(relatedType, "edit");
updateItem.setID(relatedID);
updateItem.setProperty("h4_approval_group_item", sourceID);
updateItem.setAttribute("doGetItem", "0");
updateItem.setAttribute("version","0");
updateItem.setAttribute("serverEvents","0");
updateItem = updateItem.apply();
if(updateItem.isError())
{
    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
}

return this;
